-- Loan-level records of Paycheck Protection Program (PPP) loans of $150,000 or more, including borrower, lender, amounts, and forgiveness status.
-- Auto-generated by scripts/gen_evidence_pages.py: 968,524 rows > 100k, so this is a BOUNDED pre-aggregate (parquet-safe by construction), not select *.
select year("DATEAPPROVED") as year, count(*) as records
from THE_LIBRARY.GOVERNMENT_SPENDING.FED_SBA_PPP
where "DATEAPPROVED" is not null
group by 1
order by 1
